/**
 * Retries an async HTTP request with exponential backoff.
 *
 * @param {Function} requestFn - Async function that performs the HTTP request (e.g., fetch).
 * @param {Object}   options   - Configuration options.
 * @param {number}   options.retries        - Maximum number of retry attempts (default: 3).
 * @param {number}   options.baseDelayMs    - Initial backoff delay in ms (default: 200).
 * @param {number}   options.maxDelayMs     - Upper bound for backoff delay (default: 5000).
 * @param {boolean}  options.jitter         - Apply random jitter to delay (default: true).
 * @returns {Promise<any>} The resolved value from requestFn or throws after retries exhausted.
 */
async function retryWithBackoff(requestFn, {
  retries = 3,
  baseDelayMs = 200,
  maxDelayMs = 5000,
  jitter = true,
} = {}) {
  let attempt = 0;

  while (true) {
    try {
      // Attempt the request; if it resolves, return the result.
      return await requestFn();
    } catch (err) {
      // If we've exhausted retries, rethrow the error.
      if (attempt >= retries) throw err;

      // Compute exponential backoff: baseDelay * 2^attempt
      let delay = Math.min(baseDelayMs * 2 ** attempt, maxDelayMs);

      // Optional jitter: randomize delay up to ±30% to avoid thundering herd.
      if (jitter) {
        const jitterFactor = 0.3;
        const random = Math.random() * 2 - 1; // -1 .. 1
        delay = Math.round(delay * (1 + jitterFactor * random));
      }

      // Wait before next attempt.
      await new Promise(res => setTimeout(res, delay));

      attempt++;
    }
  }
}

/* Example usage with fetch -------------------------------------------------- */
async function fetchWithRetry(url, fetchOptions) {
  return retryWithBackoff(
    () => fetch(url, fetchOptions).then(res => {
      if (!res.ok) {
        // Treat non‑2xx responses as errors to trigger a retry.
        throw new Error(`HTTP ${res.status}`);
      }
      return res.json(); // or res.text(), etc.
    }),
    { retries: 5, baseDelayMs: 300 }
  );
}

// Example call
// fetchWithRetry('https://api.example.com/data')
//   .then(data => console.log('Data:', data))
//   .catch(err => console.error('Request failed:', err));
