// LRU Cache with O(1) get and put
class ListNode {
    constructor(key, value) {
        this.key = key;
        this.value = value;
        this.prev = null;
        this.next = null;
    }
}

class LRUCache {
    /**
     * @param {number} capacity
     */
    constructor(capacity) {
        this.capacity = capacity;
        this.map = new Map();               // key -> ListNode
        // Dummy head & tail to simplify add/remove logic
        this.head = new ListNode(null, null);
        this.tail = new ListNode(null, null);
        this.head.next = this.tail;
        this.tail.prev = this.head;
    }

    // Insert node right before tail (most recently used position)
    _add(node) {
        node.prev = this.tail.prev;
        node.next = this.tail;
        this.tail.prev.next = node;
        this.tail.prev = node;
    }

    // Remove node from its current position
    _remove(node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    /**
     * @param {number} key
     * @return {number}
     */
    get(key) {
        if (!this.map.has(key)) return -1;
        const node = this.map.get(key);
        // Move accessed node to most-recent position
        this._remove(node);
        this._add(node);
        return node.value;
    }

    /**
     * @param {number} key
     * @param {number} value
     * @return {void}
     */
    put(key, value) {
        if (this.map.has(key)) {
            // Update existing node and move it to most-recent position
            const node = this.map.get(key);
            node.value = value;
            this._remove(node);
            this._add(node);
        } else {
            // Evict least-recently-used if at capacity
            if (this.map.size === this.capacity) {
                const lru = this.head.next; // first real node
                this._remove(lru);
                this.map.delete(lru.key);
            }
            // Insert new node as most-recent
            const newNode = new ListNode(key, value);
            this.map.set(key, newNode);
            this._add(newNode);
        }
    }
}

// Example usage:
// const cache = new LRUCache(2);
// cache.put(1, 1);
// cache.put(2, 2);
// console.log(cache.get(1)); // 1
// cache.put(3, 3);           // evicts key 2
// console.log(cache.get(2)); // -1
