const { Client } = require('pg');

(async () => {
  // Connect using DATABASE_URL or any other connection config
  const client = new Client({ connectionString: process.env.DATABASE_URL });
  await client.connect();

  // ---------- Schema ----------
  // Tenants table – one row per SaaS customer
  await client.query(`
    CREATE TABLE IF NOT EXISTS tenants (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      name TEXT NOT NULL,
      created_at TIMESTAMPTZ DEFAULT now()
    );
  `);

  // Data that belongs to a tenant (e.g., customers)
  await client.query(`
    CREATE TABLE IF NOT EXISTS customers (
      id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
      tenant_id UUID NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,
      email TEXT NOT NULL,
      status TEXT NOT NULL,
      created_at TIMESTAMPTZ DEFAULT now()
    );
  `);

  // ---------- Indexes ----------
  // Fast lookup by tenant (common in every query)
  await client.query(`
    CREATE INDEX IF NOT EXISTS idx_customers_tenant_id
    ON customers (tenant_id);
  `);
  // Composite index for tenant + email (e.g., login lookups)
  await client.query(`
    CREATE INDEX IF NOT EXISTS idx_customers_tenant_email
    ON customers (tenant_id, email);
  `);
  // Optional: index on status for reporting
  await client.query(`
    CREATE INDEX IF NOT EXISTS idx_customers_status
    ON customers (status);
  `);

  // ---------- Sample Query ----------
