/**
 * Checks whether a given integer is a palindrome.
 * Works for positive, negative (treated as non‑palindrome) and zero.
 *
 * @param {number} num - The integer to test.
 * @returns {boolean} True if `num` reads the same backward as forward.
 */
function isPalindromeNumber(num) {
  // Negative numbers cannot be palindromes (ignoring sign)
  if (num < 0) return false;

  // Convert number to string for easy reversal
  const str = String(num);
  const reversed = str.split('').reverse().join('');
  return str === reversed;
}

// Example usage:
console.log(isPalindromeNumber(121));   // true
console.log(isPalindromeNumber(-121));  // false
console.log(isPalindromeNumber(10));    // false
console.log(isPalindromeNumber(0));     // true
