// Returns true if x is a palindrome in base 10
bool isPalindrome(long long x) {
    if (x < 0) return false;               // negative numbers are not palindromes
    long long original = x, rev = 0;
    while (x > 0) {
        rev = rev * 10 + x % 10;            // build reversed number
        x /= 10;
    }
    return original == rev;
}

int main() {
