import java.util.concurrent.*;
import java.util.function.Consumer;

/**
 * Utility class to debounce rapid calls (e.g., search input).
 * Each call resets the timer; the provided action is executed
 * only after the specified delay has elapsed without new calls.
 */
public class Debouncer<T> implements AutoCloseable {
    private final ScheduledExecutorService scheduler;
    private final long delayMillis;
    private final Consumer<T> action;
    private ScheduledFuture<?> scheduledFuture;
    private final Object lock = new Object();

    /**
     * @param delayMillis Delay after the last call before executing the action.
     * @param action      Action to perform with the latest value.
     */
    public Debouncer(long delayMillis, Consumer<T> action) {
        this.scheduler = Executors.newSingleThreadScheduledExecutor(r -> {
            Thread t = new Thread(r);
            t.setDaemon(true);
            t.setName("debouncer-thread");
            return t;
        });
        this.delayMillis = delayMillis;
        this.action = action;
    }

    /**
     * Call this method whenever the input changes.
     * The previous scheduled execution (if any) is cancelled.
     *
     * @param value Latest input value.
     */
    public void call(T value) {
        synchronized (lock) {
            if (scheduledFuture != null && !scheduledFuture.isDone()) {
                scheduledFuture.cancel(false);
            }
            // Schedule a new execution after the debounce period
            scheduledFuture = scheduler.schedule(() -> action.accept(value),
                    delayMillis, TimeUnit.MILLISECONDS);
        }
    }

    /**
     * Shut down the internal scheduler. Call when the debouncer is no longer needed.
     */
    @Override
    public void close() {
        scheduler.shutdownNow();
    }

    // Example usage
    public static void main(String[] args) throws InterruptedException {
        // Simulate a search field that triggers a request after 300ms of inactivity
        try (Debouncer<String> searchDebouncer = new Debouncer<>(300, query -> {
            // Replace with actual search logic, e.g., HTTP request
            System.out.println("Searching for: " + query);
        })) {
            // Simulated rapid keystrokes
            searchDebouncer.call("r");
            Thread.sleep(100);
            searchDebouncer.call("re");
            Thread.sleep(100);
            searchDebouncer.call("rea");
            Thread.sleep(400); // exceeds debounce delay → triggers search for "rea"

            searchDebouncer.call("react");
            Thread.sleep(200);
            searchDebouncer.call("reactj");
            Thread.sleep(350); // triggers search for "reactj"
        }
    }
}
