import java.util.InputMismatchException;
import java.util.NoSuchElementException;
import java.util.Scanner;

/**
 * Reads two integers from standard input with strict validation
 * and prints their sum. Any invalid input results in an error
 * message and program termination.
 */
public class AddTwoNumbers {
    public static void main(String[] args) {
        // Ensure the scanner is not null (defensive guard)
        try (Scanner scanner = new Scanner(System.in)) {
            int a = readInt(scanner, "Enter first number: ");
            int b = readInt(scanner, "Enter second number: ");

            int sum = Math.addExact(a, b); // throws ArithmeticException on overflow
            System.out.println("Sum: " + sum);
        } catch (NoSuchElementException e) {
            System.err.println("Error: No input provided.");
            System.exit(1);
        } catch (ArithmeticException e) {
            System.err.println("Error: Integer overflow while computing the sum.");
            System.exit(1);
        } catch (Exception e) {
            System.err.println("Unexpected error: " + e.getMessage());
            System.exit(1);
        }
    }

    /**
     * Reads a single integer from the scanner, prompting the user.
     * Performs strict validation and aborts on any invalid input.
     *
     * @param scanner the Scanner instance (must be non‑null)
     * @param prompt  message displayed before reading
     * @return the validated integer
     */
    private static int readInt(Scanner scanner, String prompt) {
        if (scanner == null) {
            throw new IllegalArgumentException("Scanner cannot be null");
        }

        System.out.print(prompt);
        try {
            // hasNextInt ensures the next token is a valid int
            if (!scanner.hasNextInt()) {
                throw new InputMismatchException("Input is not a valid integer");
            }
            return scanner.nextInt();
        } catch (InputMismatchException e) {
            System.err.println("Error: " + e.getMessage());
            System.exit(1);
            // Unreachable, but required for compilation
            return 0;
        }
    }
}
